program key_value_store.aleo;

mapping data:
    key as u8.public;
    value as u8.public;

function insert_contains_remove:
    input r0 as u8.public;
    input r1 as u8.public;
    async insert_contains_remove r0 r1 into r2;
    output r2 as key_value_store.aleo/insert_contains_remove.future;

finalize insert_contains_remove:
    input r0 as u8.public;
    input r1 as u8.public;
    contains data[r0] into r2;
    assert.eq r2 false;
    set r1 into data[r0];
    contains data[r0] into r3;
    assert.eq r3 true;
    remove data[r0];
    contains data[r0] into r4;
    assert.eq r4 false;

function empty_remove:
    input r0 as u8.public;
    async empty_remove r0 into r1;
    output r1 as key_value_store.aleo/empty_remove.future;

finalize empty_remove:
    input r0 as u8.public;
    remove data[r0];

view get_value:
    input r0 as u8.public;
    get.or_use data[r0] 0u8 into r1;
    output r1 as u8.public;

constructor:
    assert.eq edition 0u16;

begin
   integer i;
   procedure do_it (n, L); value n; integer n; label L;
   begin
      integer array A [1 : n];
      integer i;
      for i := 1 step 1 until n do A [i] := i * i;
      if n < 10 then goto L else do_it (n - 1, L);
   end;
   outstring (1, "Example 5: arrays with non constant bounds\n");
   for i := 1 step 1 until 2000 do
   begin
      do_it (2000, L_end);
   L_end:;
   end;
end;

module examples/systems/file_system

/*
 * Model of a generic file system.
 */

abstract sig Object {}

sig Name {}

sig File extends Object {} { some d: Dir | this in d.entries.contents }

sig Dir extends Object {
  entries: set DirEntry,
  parent: lone Dir
} {
  parent = this.~@contents.~@entries
  all e1, e2 : entries | e1.name = e2.name => e1 = e2
  this !in this.^@parent
  this != Root => Root in this.^@parent
}

one sig Root extends Dir {} { no parent }

lone sig Cur extends Dir {}

sig DirEntry {
  name: Name,
  contents: Object
} {
  one this.~entries
}


/**
 * all directories besides root have one parent
 */
pred OneParent_buggyVersion {
    all d: Dir - Root | one d.parent
}

/**
 * all directories besides root have one parent
 */
pred OneParent_correctVersion {
    all d: Dir - Root | (one d.parent && one contents.d)
}

/**
 * Only files may be linked (that is, have more than one entry)
 * That is, all directories are the contents of at most one directory entry
 */
pred NoDirAliases {
    all o: Dir | lone o.~contents
}

check { OneParent_buggyVersion => NoDirAliases } for 5 expect 1

check { OneParent_correctVersion => NoDirAliases } for 5 expect 0

# A toy knapsack problem from the LocalSolver docs written in AMPL.

set I;
param Value{I};
param Weight{I};
param KnapsackBound;
var Take{I} binary;

maximize TotalValue: sum{i in I} Take[i] * Value[i];
s.t. WeightLimit: sum{i in I} Take[i] * Weight[i] <= KnapsackBound;

data;

param:
I: Weight Value :=
0    10     1
1    60    10
2    30    15
3    40    40
4    30    60
5    20    90
6    20   100
7     2    15;

param KnapsackBound := 102;

