package TbTL;

import TL::*;

interface Lamp;
   method Bool changed;
   method Action show_offs;
   method Action show_ons;
   method Action reset;
endinterface

module mkLamp#(String name, Bool lamp)(Lamp);
   Reg#(Bool) prev <- mkReg(False);

   method changed = (prev != lamp);

   method Action show_offs;
      if (prev && !lamp)
      $write (name + " off, ");
   endmethod

   method Action show_ons;
      if (!prev && lamp)
      $write (name + " on, ");
   endmethod

   method Action reset;
      prev <= lamp;
   endmethod
endmodule


