\datethis
@*Intro. This program generates clauses for the transition relation
from time $t$ to time $t+1$ in Conway's Game of Life, assuming that
all of the potentially live cells at time $t$ belong to a pattern
that's specified in |stdin|. The pattern is defined by one or more
lines representing rows of cells, where each line has `\..' in a
cell that's guaranteed to be dead at time~$t$, otherwise it has `\.*'.
The time is specified separately as a command-line parameter.

The Boolean variable for cell $(x,y)$ at time $t$ is named by its
so-called ``xty code,'' namely by the decimal value of~$x$, followed
by a code letter for~$t$, followed by the decimal value of~$y$. For
example, if $x=10$ and $y=11$ and $t=0$, the variable that indicates
liveness of the cell is \.{10a11}; and the corresponding variable
for $t=1$ is \.{10b11}.

Up to 19 auxiliary variables are used together with each xty code,
in order to construct clauses that define the successor state.
The names of these variables are obtained by appending one of
the following two-character combinations to the xty code:
\.{A2}, \.{A3}, \.{A4},
\.{B1}, \.{B2}, \.{B3}, \.{B4},
\.{C1}, \.{C2}, \.{C3}, \.{C4},
\.{D1}, \.{D2},
\.{E1}, \.{E2},
\.{F1}, \.{F2},
\.{G1}, \.{G2}.
These variables are derived from the Bailleux--Boufkhad method
of encoding cardinality constraints:
The auxiliary variable \.{A$k$} stands for the condition
``at least $k$ of the eight neighbors are alive.'' Similarly,
\.{B$k$} stands for ``at least $k$ of the first four neighbors
are alive,'' and \.{C$k$} accounts for the other four neighbors.
Codes \.D, \.E, \.F, and~\.G refer to pairs of neighbors.
Thus, for instance, \.{10a11C2} means that at least two of the
last four neighbors of cell $(10,11)$ are alive.

Those auxiliary variables receive values by means of up to 77 clauses per cell.
For example, if $u$ and~$v$ are the neighbors of cell~$z$ that correspond
to a pairing of type~\.D, there are six clauses
$$\bar u d_1,\quad
  \bar v d_1,\quad
  \bar u\bar v d_2,\quad
  u v\bar d_1,\quad
  u\bar d_2,\quad
  v\bar d_2.$$
The sixteen clauses
$$\displaylines{\hfill
\bar d_1b_1,\quad
\bar e_1b_1,\quad
\bar d_2b_2,\quad
\bar d_1\bar e_1b_2,\quad
\bar e_2b_2,\quad
\bar d_2\bar e_1b_3,\quad
\bar d_1\bar e_2b_3,\quad
\bar d_2\bar e_2b_4,
\hfill\cr\hfill
d_1e_1\bar b_1,\quad
d_1e_2\bar b_2,\quad
d_2e_1\bar b_2,\quad
d_1\bar b_3,\quad
d_2e_2\bar b_3,\quad
e_1\bar b_3,\quad
d_2\bar b_4,\quad
e_2\bar b_4
\hfill}$$
define $b$ variables from $d$'s and $e$'s; and another sixteen
define $c$'s from $f$'s and $g$'s in the same fashion.
A similar set of 21 clauses will define the $a$'s from the $b$'s and $c$'s.

Once the $a$'s are defined, thus essentially counting the
live neighbors of cell $z$, the next
state~$z'$ is defined by five further clauses
$$\bar a_4\bar z',\quad
a_2\bar z',\quad
a_3z\bar z',\quad
\bar a_3a_4z',\quad
\bar a_2a_4\bar zz'.$$
For example, the last of these states that $z'$ will be true
(i.e., that cell $z$ will be alive at time $t+1$) if
$z$ is alive at time~$t$ and has $\ge2$ live neighbors
but not $\ge4$.

Nearby cells can share auxiliary variables, according to a tricky scheme that
is worked out below. In consequence, the actual number of auxiliary variables
and clauses per cell is reduced from 19 and $77+5$ to 13 and $57+5$,
respectively, except at the boundaries.

@ So here's the overall outline of the program.

@d maxx 50 /* maximum number of lines in the pattern supplied by |stdin| */
@d maxy 50 /* maximum number of columns per line in |stdin| */

@c
#include <stdio.h>
#include <stdlib.h>
char p[maxx+2][maxy+2]; /* is cell $(x,y)$ potentially alive? */
char have_b[maxx+2][maxy+2]; /* did we already generate $b(x,y)$? */
char have_d[maxx+2][maxy+2]; /* did we already generate $d(x,y)$? */
char have_e[maxx+2][maxy+4]; /* did we already generate $e(x,y)$? */
char have_f[maxx+4][maxy+2]; /* did we already generate $f(x-2,y)$? */
int tt; /* time as given on the command line */
int xmax,ymax; /* the number of rows and columns in the input pattern */
int xmin=maxx,ymin=maxy; /* limits in the other direction */
char timecode[]="abcdefghijklmnopqrstuvwxyz"@|
      "ABCDEFGHIJKLMNOPQRSTUVWXYZ"@|
      "!\"#$%&'()*+,-./:;<=>?@@[\\]^_`{|}~"; /* codes for $0\le t\le83$ */
@q$@>
char buf[maxy+2]; /* input buffer */
unsigned int clause[4]; /* clauses are assembled here */
int clauseptr; /* this many literals are in the current clause */
@<Subroutines@>@;
main(int argc,char*argv[]) {
  register int j,k,x,y;
  @<Process the command line@>;
  @<Input the pattern@>;
  for (x=xmin-1;x<=xmax+1;x++) for (y=ymin-1;y<=ymax+1;y++) {
    @<If cell $(x,y)$ is obviously dead at time $t+1$, |continue|@>;
    a(x,y);
    zprime(x,y);
  }
}

@ @<Process the command line@>=
if (argc!=2 || sscanf(argv[1],"%d",&tt)!=1) {
  fprintf(stderr,"Usage: %s t\n",argv[0]);
  exit(-1);
}
if (tt<0 || tt>82) {
  fprintf(stderr,"The time should be between 0 and 82 (not %d)!\n",tt);
  exit(-2);
}

@ @<Input the pattern@>=
for (x=1;;x++) {
  if (!fgets(buf,maxy+2,stdin)) break;
  if (x>maxx) {
    fprintf(stderr,"Sorry, the pattern should have at most %d rows!\n",maxx);
    exit(-3);
  }
  for (y=1;buf[y-1]!='\n';y++) {
    if (y>maxy) {
      fprintf(stderr,"Sorry, the pattern should have at most %d columns!\n",
             maxy);
      exit(-4);
    }
    if (buf[y-1]=='*') {
      p[x][y]=1;
      if (y>ymax) ymax=y;
      if (y<ymin) ymin=y;
      if (x>xmax) xmax=x;
      if (x<xmin) xmin=x;
    }@+else if (buf[y-1]!='.') {
      fprintf(stderr,"Unexpected character `%c' found in the pattern!\n",
              buf[y-1]);
      exit(-5);
    }
  }
}

@ @d pp(xx,yy) ((xx)>=0 && (yy)>=0? p[xx][yy]: 0)

@<If cell $(x,y)$ is obviously dead at time $t+1$, |continue|@>=
if (pp(x-1,y-1)+pp(x-1,y)+pp(x-1,y+1)+
    pp(x,y-1)+p[x][y]+p[x][y+1]+
    pp(x+1,y-1)+p[x+1][y]+p[x+1][y+1]<3) continue;

@ Clauses are assembled in the |clause| array (surprise), where we
put encoded literals.

The code for a literal is an unsigned 32-bit quantity, where the leading
bit is 1 if the literal should be complemented. The next three bits
specify the type of the literal (0 thru 7 for plain and \.A--\.G);
the next three bits specify an integer~$k$; and the next bit is zero.
That leaves room for two 12-bit fields, which specify $x$ and $y$.

Type 0 literals have $k=0$ for the ordinary xty code. However, the
value $k=1$ indicates that the time code should be for $t+1$ instead of~$t$.
And $k=2$ denotes a special ``tautology'' literal, which is always true.
If the tautology literal is complemented, we omit it from the clause;
otherwise we omit the entire clause.
Finally, $k=7$ denotes an auxiliary literal, used to avoid
clauses of length~4.

Here's a subroutine that outputs the current clause and resets
the |clause| array.

@d taut (2<<25)
@d sign (1U<<31)

@<Sub...@>=
void outclause(void) {
  register int c,k,x,y,p;
  for (p=0;p<clauseptr;p++)
    if (clause[p]==taut) goto done;
  for (p=0;p<clauseptr;p++) if (clause[p]!=taut+sign) {
    if (clause[p]>>31) printf(" ~");@+else printf(" ");
    c=(clause[p]>>28)&0x7;
    k=(clause[p]>>25)&0x7;
    x=(clause[p]>>12)&0xfff;
    y=clause[p]&0xfff;
    if (c) printf("%d%c%d%c%d",
             x,timecode[tt],y,c+'@@',k);
    else if (k==7) printf("%d%c%dx",
             x,timecode[tt],y);
    else printf("%d%c%d",
             x,timecode[tt+k],y);
  }
  printf("\n");
done: clauseptr=0;
}

@ And here's another, which puts a type-0 literal into |clause|.

@<Sub...@>=
void applit(int x,int y,int bar,int k) {
  if (k==0 && (x<xmin || x>xmax || y<ymin || y>ymax || p[x][y]==0))
    clause[clauseptr++]=(bar? 0: sign)+taut;
  else clause[clauseptr++]=(bar? sign:0)+(k<<25)+(x<<12)+y;
}

@ The |d| and |e| subroutines are called for only one-fourth
of all cell addresses $(x,y)$. Indeed, one can show that
$x$ is always odd, and that $y\bmod4<2$.

Therefore we remember if we've seen $(x,y)$ before.

Slight trick: If |yy| is not in range, we avoid generating the
clause $\bar d_k$ twice.

@d newlit(x,y,c,k) clause[clauseptr++]=((c)<<28)+((k)<<25)+((x)<<12)+(y)
@d newcomplit(x,y,c,k) 
   clause[clauseptr++]=sign+((c)<<28)+((k)<<25)+((x)<<12)+(y)

@<Sub...@>=
void d(int x,int y) {
  register x1=x-1,x2=x,yy=y+1;
  if (have_d[x][y]!=tt+1) {
    applit(x1,yy,1,0),newlit(x,y,4,1),outclause();
    applit(x2,yy,1,0),newlit(x,y,4,1),outclause();
    applit(x1,yy,1,0),applit(x2,yy,1,0),newlit(x,y,4,2),outclause();
    applit(x1,yy,0,0),applit(x2,yy,0,0),newcomplit(x,y,4,1),outclause();
    applit(x1,yy,0,0),newcomplit(x,y,4,2),outclause();
    if (yy>=ymin && yy<=ymax)
      applit(x2,yy,0,0),newcomplit(x,y,4,2),outclause();
    have_d[x][y]=tt+1;
  }
}
@#
void e(int x,int y) {
  register x1=x-1,x2=x,yy=y-1;
  if (have_e[x][y]!=tt+1) {
    applit(x1,yy,1,0),newlit(x,y,5,1),outclause();
    applit(x2,yy,1,0),newlit(x,y,5,1),outclause();
    applit(x1,yy,1,0),applit(x2,yy,1,0),newlit(x,y,5,2),outclause();
    applit(x1,yy,0,0),applit(x2,yy,0,0),newcomplit(x,y,5,1),outclause();
    applit(x1,yy,0,0),newcomplit(x,y,5,2),outclause();
    if (yy>=ymin && yy<=ymax)
      applit(x2,yy,0,0),newcomplit(x,y,5,2),outclause();
    have_e[x][y]=tt+1;
  }
}

@ The |f| subroutine can't be shared quite so often. But we
do save a factor of~2, because $x+y$ is always even.

@<Sub...@>=
void f(int x,int y) {
  register xx=x-1,y1=y,y2=y+1;
  if (have_f[x][y]!=tt+1) {
    applit(xx,y1,1,0),newlit(x,y,6,1),outclause();
    applit(xx,y2,1,0),newlit(x,y,6,1),outclause();
    applit(xx,y1,1,0),applit(xx,y2,1,0),newlit(x,y,6,2),outclause();
    applit(xx,y1,0,0),applit(xx,y2,0,0),newcomplit(x,y,6,1),outclause();
    applit(xx,y1,0,0),newcomplit(x,y,6,2),outclause();
    if (xx>=xmin && xx<=xmax)
      applit(xx,y2,0,0),newcomplit(x,y,6,2),outclause();
    have_f[x][y]=tt+1;
  }
}

@ The |g| subroutine cleans up the dregs, by somewhat tediously
locating the two neighbors that weren't handled by |d|, |e|, or~|f|.
No sharing is possible here.

@<Sub...@>=
void g(int x,int y) {
  register x1,x2,y1,y2;
  if (x&1) x1=x-1,y1=y,x2=x+1,y2=y^1;
  else x1=x+1,y1=y,x2=x-1,y2=y-1+((y&1)<<1);
  applit(x1,y1,1,0),newlit(x,y,7,1),outclause();
  applit(x2,y2,1,0),newlit(x,y,7,1),outclause();
  applit(x1,y1,1,0),applit(x2,y2,1,0),newlit(x,y,7,2),outclause();
  applit(x1,y1,0,0),applit(x2,y2,0,0),newcomplit(x,y,7,1),outclause();
  applit(x1,y1,0,0),newcomplit(x,y,7,2),outclause();
  applit(x2,y2,0,0),newcomplit(x,y,7,2),outclause();
}

@ Fortunately the |b| subroutine {\it can\/} be shared (since |x| is always
odd), thus saving half of the sixteen clauses generated.

@<Sub...@>=
void b(int x,int y) {
  register j,k,xx=x,y1=y-(y&2),y2=y+(y&2);
  if (have_b[x][y]!=tt+1) {
    d(xx,y1);
    e(xx,y2);
    for (j=0;j<3;j++) for (k=0;k<3;k++) if (j+k) {
      if (j) newcomplit(xx,y1,4,j); /* $\bar d_j$ */
      if (k) newcomplit(xx,y2,5,k); /* $\bar e_k$ */
      newlit(x,y,2,j+k); /* $b_{j+k}$ */
      outclause();
      if (j) newlit(xx,y1,4,3-j); /* $d_{3-j}$ */
      if (k) newlit(xx,y2,5,3-k); /* $e_{3-k}$ */
      newcomplit(x,y,2,5-j-k); /* $\bar b_{5-j-k}$ */
      outclause();      
    }
    have_b[x][y]=tt+1;
  }
}

@ The (unshared) |c| subroutine handles the other four neighbors,
by working with |f| and |g| instead of |d| and~|e|.

If |y=0|, the overlap rules set |y1=-1|, which can be problematic.
I've decided to avoid this case by omitting |f| when it is
guaranteed to be zero.

@<Sub...@>=
void c(int x,int y) {
  register j,k,x1,y1;
  if (x&1) x1=x+2,y1=(y-1)|1;
  else x1=x,y1=y&-2;
  g(x,y);
  if (x1-1<xmin || x1-1>xmax || y1+1<ymin || y1>ymax)
    @<Set |c| equal to |g|@>@;
  else {
    f(x1,y1);
    for (j=0;j<3;j++) for (k=0;k<3;k++) if (j+k) {
      if (j) newcomplit(x1,y1,6,j); /* $\bar f_j$ */
      if (k) newcomplit(x,y,7,k); /* $\bar g_k$ */
      newlit(x,y,3,j+k); /* $c_{j+k}$ */
      outclause();
      if (j) newlit(x1,y1,6,3-j); /* $f_{3-j}$ */
      if (k) newlit(x,y,7,3-k); /* $g_{3-k}$ */
      newcomplit(x,y,3,5-j-k); /* $\bar c_{5-j-k}$ */
      outclause();
    }
  }
}

@ @<Set |c| equal to |g|@>=
{
  for (k=1;k<3;k++) {
    newcomplit(x,y,7,k),newlit(x,y,3,k),outclause(); /* $\bar g_k\lor c_k$ */
    newlit(x,y,7,k),newcomplit(x,y,3,k),outclause(); /* $g_k\lor\bar c_k$ */
  }
  newcomplit(x,y,3,3),outclause(); /* $\bar c_3$ */
  newcomplit(x,y,3,4),outclause(); /* $\bar c_4$ */
}

@ Totals over all eight neighbors are then deduced by the |a|
subroutine.

@<Sub...@>=
void a(int x,int y) {
  register j,k,xx=x|1;
  b(xx,y);
  c(x,y);
  for (j=0;j<5;j++) for (k=0;k<5;k++) if (j+k>1 && j+k<5) {
    if (j) newcomplit(xx,y,2,j); /* $\bar b_j$ */
    if (k) newcomplit(x,y,3,k); /* $\bar c_k$ */
    newlit(x,y,1,j+k); /* $a_{j+k}$ */
    outclause();
  }
  for (j=0;j<5;j++) for (k=0;k<5;k++) if (j+k>2 && j+k<6 && j*k) {
    if (j) newlit(xx,y,2,j); /* $b_j$ */
    if (k) newlit(x,y,3,k); /* $c_k$ */
    newcomplit(x,y,1,j+k-1); /* $\bar a_{j+k-1}$ */
    outclause();
  }
}

@ Finally, as mentioned at the beginning, $z'$ is determined
from $z$, $a_2$, $a_3$, and $a_4$.

I actually generate six clauses, not five, in order to stick to
{\mc 3SAT}.

@<Sub...@>=
void zprime(int x,int y) {
  newcomplit(x,y,1,4),applit(x,y,1,1),outclause(); /* $\bar a_4\bar z'$ */
  newlit(x,y,1,2),applit(x,y,1,1),outclause(); /* $a_2\bar z'$ */
  newlit(x,y,1,3),applit(x,y,0,0),applit(x,y,1,1),outclause();
               /* $a_3z\bar z'$ */
  newcomplit(x,y,1,3),newlit(x,y,1,4),applit(x,y,0,1),outclause();
               /* $\bar a_3a_4z'$ */
  applit(x,y,0,7),newcomplit(x,y,1,2),newlit(x,y,1,4),outclause();
               /* $x\bar a_2a_4$ */
  applit(x,y,1,7),applit(x,y,1,0),applit(x,y,0,1),outclause();
               /* $\bar x\bar zz'$ */
}

@*Index.

(function(utils) {
	// Load C functions declared in utils.loadFuncs
	var shouldLoadCFuncs = true;
	// Expose the C functions to cycript's global scope
	var shouldExposeCFuncs = true;
	// Expose C constants to cycript's global scope
	var shouldExposeConsts = true;
	// Expose functions defined here to cycript's global scope
	var shouldExposeFuncs = true;
	// Which functions to expose
	var funcsToExpose = ["exec", "include", "sizeof", "logify", "apply", "str2voidPtr", "voidPtr2str", "double2voidPtr", "voidPtr2double", "isMemoryReadable", "isObject", "makeStruct"];

	// C functions that utils.loadFuncs loads
	var CFuncsDeclarations = [
		// <stdlib.h>
		"void *calloc(size_t num, size_t size)",
		// <string.h>
		"char *strcpy(char *restrict dst, const char *restrict src)",
		"char *strdup(const char *s1)",
		"void* memset(void* dest, int ch, size_t count)",
		// <stdio.h>
		"FILE *fopen(const char *, const char *)",
		"int fclose(FILE *)",
		"size_t fread(void *restrict, size_t, size_t, FILE *restrict)",
		"size_t fwrite(const void *restrict, size_t, size_t, FILE *restrict)",
		// <mach.h>
		"mach_port_t mach_task_self()",
		"kern_return_t task_for_pid(mach_port_name_t target_tport, int pid, mach_port_name_t *tn)",
		"kern_return_t mach_vm_protect(vm_map_t target_task, mach_vm_address_t address, mach_vm_size_t size, boolean_t set_maximum, vm_prot_t new_protection)",
		"kern_return_t mach_vm_write(vm_map_t target_task, mach_vm_address_t address, vm_offset_t data, mach_msg_type_number_t dataCnt)",
		"kern_return_t mach_vm_read(vm_map_t target_task, mach_vm_address_t address, mach_vm_size_t size, vm_offset_t *data, mach_msg_type_number_t *dataCnt)",
	];

	/*
		Replacement for eval that can handle @encode etc.

		Usage:
			cy# utils.exec("@encode(void *(int, char))")
			@encode(void*(int,char))
	*/
	utils.exec = function(str) {
		var mkdir = @encode(int (const char *, int))(dlsym(RTLD_DEFAULT, "mkdir"));
		var tempnam = @encode(char *(const char *, const char *))(dlsym(RTLD_DEFAULT, "tempnam"));
		var fopen = @encode(void *(const char *, const char *))(dlsym(RTLD_DEFAULT, "fopen"));
		var fclose = @encode(int (void *))(dlsym(RTLD_DEFAULT, "fclose"));
		var fwrite = @encode(int (const char *, int, int, void *))(dlsym(RTLD_DEFAULT, "fwrite"));
		var symlink = @encode(int (const char *, const char *))(dlsym(RTLD_DEFAULT, "symlink"));
		var unlink = @encode(int (const char *))(dlsym(RTLD_DEFAULT, "unlink"));
		var getenv = @encode(const char *(const char *))(dlsym(RTLD_DEFAULT, "getenv"));
		var setenv = @encode(int (const char *, const char *, int))(dlsym(RTLD_DEFAULT, "setenv"));

		var libdir = "/usr/lib/cycript0.9";
		var dir = libdir + "/tmp";

		mkdir(dir, 0777);

		// This is needed because tempnam seems to ignore the first argument on i386
		var old_tmpdir = getenv("TMPDIR");
		setenv("TMPDIR", dir, 1);

		// No freeing :(
		var f = tempnam(dir, "exec-");
		setenv("TMPDIR", old_tmpdir, 1);
		if(!f) {
			return false;
		}

		symlink(f, f + ".cy");

		str = "exports.result = " + str;

		var handle = fopen(f, "w");
		fwrite(str, str.length, 1, handle);
		fclose(handle);

		var r;
		var except = null;
		try {
			r = require(f.replace(libdir + "/", ""));
		} catch(e) {
			except = e;
		}

		unlink(f + ".cy");
		unlink(f);

		if(except !== null) {
			throw except;
		}

		return r.result;
	};

	/*
		Applies known typedefs
		Used in utils.include and utils.makeStruct

		Usage:
			cy# utils.applyTypedefs("mach_vm_address_t")
			"uint64_t"
	*/
	utils.applyTypedefs = function(str) {
		var typedefs = {
			"struct": "",
			"restrict": "",
			"FILE": "void",
			"size_t": "uint64_t",
			"uintptr_t": "unsigned long",
			"kern_return_t": "int",
			"mach_port_t": "unsigned int",
			"mach_port_name_t": "unsigned int",
			"vm_offset_t": "unsigned long",
			"vm_size_t": "unsigned long",
			"mach_vm_address_t": "uint64_t",
			"mach_vm_offset_t": "uint64_t",
			"mach_vm_size_t": "uint64_t",
			"vm_map_offset_t": "uint64_t",
			"vm_map_address_t": "uint64_t",
			"vm_map_size_t": "uint64_t",
			"mach_port_context_t": "uint64_t",
			"vm_map_t": "unsigned int",
			"boolean_t": "unsigned int",
			"vm_prot_t": "int",
			"mach_msg_type_number_t": "unsigned int",
			"cpu_type_t": "int",
			"cpu_subtype_t": "int",
			"cpu_threadtype_t": "int",
		};

		for(var k in typedefs) {
			str = str.replace(new RegExp("(\\s|\\*|,|\\(|^)" + k + "(\\s|\\*|,|\\)|$)", "g"), "$1" + typedefs[k] + "$2");
		}

		return str;
	};

	/*
		Parses a C function declaration and returns the function name and cycript type
		If load is true, tries to load it into cycript using utils.exec

		Usage:
			cy# var str = "void *calloc(size_t num, size_t size)";
			"void *calloc(size_t num, size_t size)"
			cy# utils.include(str)
			["calloc","@encode(void *(uint64_t num,  uint64_t size))(140735674376857)"]
			cy# var ret = utils.include(str, true)
			["calloc",0x7fff93e0e299]
			cy# ret[1].type
			@encode(void*(unsigned long long int,unsigned long long int))
			cy# ret[1](100, 1)
			0x100444100
	*/
	utils.include = function(str, load) {
		var re = /^\s*([^(]*(?:\s+|\*))(\w*)\s*\(([^)]*)\)\s*;?\s*$/;
		var match = re.exec(str);
		if(!match) {
			return -1;
		}
		var rType = utils.applyTypedefs(match[1]);
		var name = match[2];
		var args = match[3];

		var argsRe = /([^,]+)(?:,|$)/g;
		var argsTypes = [];
		while((match = argsRe.exec(args)) !== null) {
			var type = utils.applyTypedefs(match[1]);
			argsTypes.push(type);
		}

		var encodeString = "@encode(";
		encodeString += rType + "(";
		encodeString += argsTypes.join(", ") + "))";

		var fun = dlsym(RTLD_DEFAULT, name);
		if(fun !== null) {
			encodeString += "(" + fun + ")";
			if(load) {
				return [name, utils.exec(encodeString)];
			}
		} else if(load) {
			throw "Function couldn't be found with dlsym!";
		}

		return [name, encodeString];
	};

	/*
		Loads the function declaration in the defs array using utils.exec and exposes to cycript's global scope
		Is automatically called if shouldLoadCFuncs is true
	*/
	utils.funcs = {};
	utils.loadfuncs = function(expose) {
		for(var i = 0; i < CFuncsDeclarations.length; i++) {
			try {
				var o = utils.include(CFuncsDeclarations[i], true);
				utils.funcs[o[0]] = o[1];
				if(expose) {
					Cycript.all[o[0]] = o[1];
				}
			} catch(e) {
				system.print("Failed to load function: " + i);
				try {
					system.print(utils.include(CFuncsDeclarations[i]));
				} catch(e2) {

				}
			}
		}
	};

	/*
		Calculates the size of a type like the C operator sizeof

		Usage:
			cy# utils.sizeof(int)
			4
			cy# utils.sizeof(@encode(void *))
			8
			cy# utils.sizeof("mach_vm_address_t")
			8
	*/
	utils.sizeof = function(type) {
		if(typeof type === "string") {
			type = utils.applyTypedefs(type);
			type = utils.exec("@encode(" + type + ")");
		}

		// (const) char * has "infinite" preceision
		if(type.toString().slice(-1) === "*") {
			return utils.sizeof(@encode(void *));
		}

		// float and double
		if(type.toString() === @encode(float).toString()) {
			return 4;
		} else if (type.toString() === @encode(double).toString()) {
			return 8;
		}

		var typeInstance = type(0);

		if(typeInstance instanceof Object) {
			// Arrays
			if("length" in typeInstance) {
				return typeInstance.length * utils.sizeof(typeInstance.type);
			}

			// Structs
			if(typeInstance.toString() === "[object Struct]") {
				var typeStr = type.toString();
				var arrayTypeStr = "[2" + typeStr + "]";
				var arrayType = new Type(arrayTypeStr);

				var arrayInstance = new arrayType;

				return @encode(void *)(&(arrayInstance[1])) - @encode(void *)(&(arrayInstance[0]));
			}
		}

		for(var i = 0; i < 5; i++) {
			var maxSigned = Math.pow(2, 8 * Math.pow(2, i) - 1) - 1;
			if(i === 3) {
				// Floating point fix ;^)
				maxSigned /= 1000;
			}

			// can't use !== or sizeof(void *) === 0.5
			if(type(maxSigned) != maxSigned) {
				return Math.pow(2, i - 1);
			}
		}
	};

	/*
		Logs a specific message sent to an instance of a class like logify.pl in theos
		Requires Cydia Substrate (com.saurik.substrate.MS) and NSLog (org.cycript.NSLog) modules
		Returns the old message returned by MS.hookMessage (Note: this is not just the old message!)

		Usage:
			cy# var oldm = utils.logify(objc_getMetaClass(NSNumber), @selector(numberWithDouble:))
			...
			cy# var n = [NSNumber numberWithDouble:1.5]
			2014-07-28 02:26:39.805 cycript[71213:507] +[<NSNumber: 0x10032d0c4> numberWithDouble:1.5]
			2014-07-28 02:26:39.806 cycript[71213:507]  = 1.5
			@1.5
	*/
	utils.logify = function(cls, sel) {
		@import com.saurik.substrate.MS;
		@import org.cycript.NSLog;

		var oldm = {};

		MS.hookMessage(cls, sel, function() {
			var args = [].slice.call(arguments);

			var selFormat = sel.toString().replace(/:/g, ":%@ ").trim();
			var logFormat = "%@[<%@: 0x%@> " + selFormat + "]";

			var standardArgs = [logFormat, class_isMetaClass(cls)? "+": "-", cls.toString(), (&this).valueOf().toString(16)];
			var logArgs = standardArgs.concat(args);

			NSLog.apply(null, logArgs);

			var r = oldm->apply(this, arguments);

			if(r !== undefined) {
				NSLog(" = %@", r);
			}

			return r;
		}, oldm);

		return oldm;
	};

	/*
		Calls a C function by providing its name and arguments
		Doesn't support structs
		Return value is always a void pointer

		Usage:
			cy# utils.apply("printf", ["%s %.3s, %d -> %c, float: %f\n", "foo", "barrrr", 97, 97, 1.5])
			foo bar, 97 -> a, float: 1.500000
			0x22
	*/
	utils.apply = function(fun, args) {
		if(!(args instanceof Array)) {
			throw "Args needs to be an array!";
		}

		var argc = args.length;
		var voidPtr = @encode(void *);
		var argTypes = [];
		for(var i = 0; i < argc; i++) {
			var argType = voidPtr;

			var arg = args[i];
			if(typeof arg === "string") {
				argType = @encode(char *);
			}
			if(typeof arg === "number" && arg % 1 !== 0) {
				argType = @encode(double);
			}

			argTypes.push(argType);
		}

		var type = voidPtr.functionWith.apply(voidPtr, argTypes);

		if(typeof fun === "string") {
			fun = dlsym(RTLD_DEFAULT, fun);
		}

		if(!fun) {
			throw "Function not found!";
		}

		return type(fun).apply(null, args);
	};

	/*
		Converts a string (char *) to a void pointer (void *)
		You can't cast to strings to void pointers and vice versa in cycript. Blame saurik.

		Usage:
			cy# var voidPtr = utils.str2voidPtr("foobar")
			0x100331590
			cy# utils.voidPtr2str(voidPtr)
			"foobar"
	*/
	utils.str2voidPtr = function(str) {
		var strdup = @encode(void *(char *))(dlsym(RTLD_DEFAULT, "strdup"));
		return strdup(str);
	};

	/*
		The inverse function of str2voidPtr
	*/
	utils.voidPtr2str = function(voidPtr) {
		var strdup = @encode(char *(void *))(dlsym(RTLD_DEFAULT, "strdup"));
		return strdup(voidPtr);
	};

	/*
		Converts a double into a void pointer
		This can be used to view the binary representation of a floating point number

		Usage:
			cy# var n = utils.double2voidPtr(-1.5)
			0xbff8000000000000
			cy# utils.voidPtr2double(n)
			-1.5
	*/
	utils.double2voidPtr = function(n) {
		var doublePtr = new double;
		*doublePtr = n;

		var voidPtrPtr = @encode(void **)(doublePtr);

		return *voidPtrPtr;
	};

	/*
		The inverse function of double2voidPtr
	*/
	utils.voidPtr2double = function(voidPtr) {
		var voidPtrPtr = new @encode(void **);
		*voidPtrPtr = voidPtr;

		var doublePtr = @encode(double *)(voidPtrPtr);

		return *doublePtr;
	};

	/*
		Determines in a safe way if a memory location is readable

		Usage:
			cy# utils.isMemoryReadable(0)
			false
			cy# utils.isMemoryReadable(0x1337)
			false
			cy# utils.isMemoryReadable(NSObject)
			true
			cy# var a = malloc(100); utils.isMemoryReadable(a)
			true
	*/
	utils.isMemoryReadable = function(ptr) {
		if(typeof ptr === "string") {
			return true;
		}

		var fds = new @encode(int [2]);
		utils.apply("pipe", [fds]);
		var result = utils.apply("write", [fds[1], ptr, 1]) == 1;

		utils.apply("close", [fds[0]]);
		utils.apply("close", [fds[1]]);

		return result;
	};

	/*
		Determines in a safe way if the memory location contains an Objective-C object

		Usage:
			cy# utils.isObject(0)
			false
			cy# utils.isObject(0x1337)
			false
			cy# utils.isObject(NSObject)
			true
			cy# utils.isObject(objc_getMetaClass(NSObject))
			true
			cy# utils.isObject([new NSObject init])
			true
			cy# var a = malloc(100); utils.isObject(a)
			false
			cy# *@encode(void **)(a) = NSObject; utils.isObject(a)
			true
	*/
	utils.isObject = function(obj) {
		obj = @encode(void *)(obj);
		var lastObj = -1;

		function objc_isa_ptr(obj) {
			// See http://www.sealiesoftware.com/blog/archive/2013/09/24/objc_explain_Non-pointer_isa.html
			var objc_debug_isa_class_mask = 0x00000001fffffffa;
			obj = (obj & 1)? (obj & objc_debug_isa_class_mask): obj;

			if((obj & (utils.sizeof(@encode(void *)) - 1)) != 0) {
				return null;
			} else {
				return obj;
			}
		}

		function ptrValue(obj) {
			return obj? obj.valueOf(): null;
		}

		var foundMetaClass = false;

		for(obj = objc_isa_ptr(obj); utils.isMemoryReadable(obj); ) {
			obj = *@encode(void **)(obj);

			if(ptrValue(obj) == ptrValue(lastObj)) {
				foundMetaClass = true;
				break;
			}

			lastObj = obj;
		}

		if(!foundMetaClass) {
			return false;
		}

		if(lastObj === -1 || lastObj === null) {
			return false;
		}

		var obj_class = objc_isa_ptr(@encode(void **)(obj)[1]);

		if(!utils.isMemoryReadable(obj_class)) {
			return false;
		}

		var metaclass = objc_isa_ptr(@encode(void **)(obj_class)[0]);
		var superclass = objc_isa_ptr(@encode(void **)(obj_class)[1]);

		return ptrValue(obj) == ptrValue(metaclass) && superclass == null;
	};

	/*
		Creates a cycript struct type from a C struct definition

		Usage:
			cy# var foo = makeStruct("int a; short b; char c; uint64_t d; double e;", "foo");
			@encode(foo)
			cy# var f = new foo
			&{a:0,b:0,c:0,d:0,e:0}
			cy# f->a = 100; f
			&{a:100,b:0,c:0,d:0,e:0}
			cy# *@encode(int *)(f)
			100
	*/
	utils.makeStruct = function(str, name) {		
		var fieldRe = /(?:\s|\n)*([^;]+\s*(?:\s|\*))([^;]+)\s*;/g;

		if(!name) {
			name = "struct" + Math.floor(Math.random() * 100000);
		}
		var typeStr = "{" + name + "=";

		while((match = fieldRe.exec(str)) !== null) {
			var fieldType = utils.applyTypedefs(match[1]);
			var fieldName = match[2];
			var encodedType = utils.exec("@encode(" + fieldType + ")").toString();

			typeStr += '"' + fieldName + '"' + encodedType;
		}

		typeStr += "}";

		return new Type(typeStr);
	};

	// Various constants
	utils.constants = {
		VM_PROT_NONE:       0x0,
		VM_PROT_READ:       0x1,
		VM_PROT_WRITE:      0x2,
		VM_PROT_EXECUTE:    0x4,
		VM_PROT_NO_CHANGE:  0x8,
		VM_PROT_COPY:       0x10,
		VM_PROT_WANTS_COPY: 0x10,
		VM_PROT_IS_MASK:    0x40,
	};
	var c = utils.constants;
	c.VM_PROT_DEFAULT = c.VM_PROT_READ | c.VM_PROT_WRITE;
	c.VM_PROT_ALL =     c.VM_PROT_READ | c.VM_PROT_WRITE | c.VM_PROT_EXECUTE;

	if(shouldExposeConsts) {
		for(var k in c) {
			Cycript.all[k] = c[k];
		}
	}

	if(shouldExposeFuncs) {
		for(var i = 0; i < funcsToExpose.length; i++) {
			var name = funcsToExpose[i];
			Cycript.all[name] = utils[name];
		}
	}

	if(shouldLoadCFuncs) {
		utils.loadfuncs(shouldExposeCFuncs);
	}
})(exports);

