        fmt.println("conj(q) =", conj(q));
        fmt.println("abs(q)  =", abs(q));
    }
    { // Conversion of a complex type to a quaternion type
        c := 1 + 2i;
        q := quaternion256(c);
        fmt.println(c);
        fmt.println(q);
    }
    { // Memory layout of Quaternions
