function bubblesort(list as int[]) as int[] {
    var manipulated = true;

    while(manipulated) {
    	manipulated = false;
        for i in 1 .. list.length {
            if(list[i - 1] > list[i]) {
                manipulated = true;
                //Swap
                val temp = list[i - 1];
                list[i - 1] = list[i];
                list[i] = temp;
            }
        }
    }

    return list;
}


